	@ParameterizedTest
	@MethodSource("codecs")
	void boundedChunksMatchTheRawVisitorAcrossFramesAndRetainTheirArrays(BulkCodec codec) throws Exception {
		List<ExpectedStatement> expected = expectedStatements();
		writeFrames(statementPath(), codec, expected);
		CanonicalStagedInput input = stagedInput(codec, expected.size());

		List<String> visitorRecords = new ArrayList<>();
		input.forEachRawStatement((ordinal, subject, predicate, object, context) -> visitorRecords
				.add(view(ordinal, subject, predicate, object, context)));
		List<String> cursorRecords = new ArrayList<>();
		byte[] retainedSubject;
		byte[] retainedSnapshot;
		try (CanonicalStagedInput.RawStatementCursor cursor = input.openRawStatementCursor()) {
			CanonicalStagedInput.RawStatementChunk first = cursor.nextChunk(Long.MAX_VALUE, 2);
			assertThat(first.records()).hasSize(2);
			retainedSubject = first.records().getFirst().subject();
			retainedSnapshot = retainedSubject.clone();
			append(cursorRecords, first.records());
			CanonicalStagedInput.RawStatementChunk last = cursor.nextChunk(Long.MAX_VALUE, 2);
			assertThat(last.records()).hasSize(1);
			append(cursorRecords, last.records());
			assertThat(cursor.nextChunk(Long.MAX_VALUE, 2)).isNull();
			assertThat(cursor.peekNextRecordRetainedBytes()).isEqualTo(-1L);
		}

		assertThat(retainedSubject).containsExactly(retainedSnapshot);
		assertThat(cursorRecords).containsExactlyElementsOf(visitorRecords);
		assertThat(cursorRecords).containsExactlyElementsOf(expected.stream()
				.map(statement -> view(statement.ordinal(), statement.subject(), statement.predicate(),
						statement.object(),
						statement.context()))
				.toList());
	}

